/**
 * QODIQA Webhook Protocol — JavaScript SDK Conformance Test
 *
 * Loads the shared, language-neutral vector file (test-vectors/webhook-v1.json)
 * and verifies every vector with the real, unmodified JS SDK verifier. No
 * signature is generated in this file — every `expectedSignature` and every
 * `verify.signature` value comes straight from the checked-in vector file,
 * which was itself generated by calling the production server's signer (see
 * test-vectors/README.md).
 *
 * This test's only job is to catch SDK-side drift from the shared protocol
 * contract. Server-side drift is caught independently by
 * src/core/webhooks/__tests__/webhookProtocolConformance.test.js.
 */

import fs from 'node:fs';
import path from 'node:path';
import {
  verifyWebhookSignature,
  InvalidSignatureError,
  ExpiredSignatureError,
  MalformedSignatureError,
  InvalidTimestampError,
  QodiqaError,
} from '../src/index';

// ---------------------------------------------------------------------------
// Load the shared vector file
// ---------------------------------------------------------------------------

const VECTORS_PATH = path.resolve(__dirname, '../../../test-vectors/webhook-v1.json');
const vectorFile = JSON.parse(fs.readFileSync(VECTORS_PATH, 'utf8'));
const vectors: Array<Record<string, any>> = vectorFile.vectors;

// Canonical error-category name -> real JS SDK error class.
const ERROR_CLASS_BY_NAME: Record<string, new (...args: any[]) => QodiqaError> = {
  MalformedSignatureError,
  InvalidTimestampError,
  ExpiredSignatureError,
  InvalidSignatureError,
};

/** Parse an ISO-8601 UTC timestamp into epoch seconds. */
function epochSeconds(isoTimestamp: string): number {
  return Date.parse(isoTimestamp) / 1000;
}

// ---------------------------------------------------------------------------
// Sanity checks on the shared file itself
// ---------------------------------------------------------------------------

describe('webhook protocol conformance — shared vector file', () => {
  it('loads and is non-empty', () => {
    expect(Array.isArray(vectors)).toBe(true);
    expect(vectors.length).toBeGreaterThan(0);
  });

  it('vectorCount metadata matches the actual vector array', () => {
    const positive = vectors.filter((v) => v.expectedResult === 'valid').length;
    const negative = vectors.filter((v) => v.expectedResult === 'invalid').length;
    expect(vectorFile.vectorCount.positive).toBe(positive);
    expect(vectorFile.vectorCount.negative).toBe(negative);
    expect(vectorFile.vectorCount.total).toBe(vectors.length);
  });

  it('declares protocol version v1', () => {
    expect(vectorFile.protocolVersion).toBe('v1');
  });
});

// ---------------------------------------------------------------------------
// Conformance — every vector, driven entirely by the shared file
// ---------------------------------------------------------------------------

describe('webhook protocol conformance — JS SDK verifier', () => {
  for (const vector of vectors) {
    const { verify, expectedResult, expectedError, id } = vector;

    it(`vector "${id}" (${expectedResult})`, () => {
      const call = () =>
        verifyWebhookSignature({
          body: verify.body,
          signature: verify.signature,
          timestamp: verify.timestamp,
          secret: verify.secrets,
          tolerance: verify.tolerance,
          _now: epochSeconds(verify.verifyAt),
        });

      if (expectedResult === 'valid') {
        expect(call).not.toThrow();
        return;
      }

      const ExpectedClass = ERROR_CLASS_BY_NAME[expectedError as string];
      expect(ExpectedClass).toBeDefined();
      expect(call).toThrow(ExpectedClass);
    });
  }

  it('every negative vector fails closed with a QodiqaError subclass', () => {
    for (const vector of vectors) {
      if (vector.expectedResult !== 'invalid') continue;
      const { verify } = vector;
      expect(() =>
        verifyWebhookSignature({
          body: verify.body,
          signature: verify.signature,
          timestamp: verify.timestamp,
          secret: verify.secrets,
          tolerance: verify.tolerance,
          _now: epochSeconds(verify.verifyAt),
        }),
      ).toThrow(QodiqaError);
    }
  });
});
